<?php
$p=json_decode($argv[1],true,512,JSON_THROW_ON_ERROR);
$path=$p['path']; if(strncmp($path,'/',1)!==0 || strncmp($path,'//',2)===0)throw new Exception('Expected local relative path');
$headers=array_merge(['X-Compat-Case: '.$p['marker']],$p['headers']??[]);
if(!empty($p['browser']))$headers=array_merge($headers,['Accept: text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8','Accept-Language: en-US,en;q=0.9','Accept-Encoding: gzip, deflate']);
$ua=$p['ua']??('python-requests/2.32.3 Compat-'.$p['marker']);
$c=curl_init('http://127.0.0.1:'.($p['port']??8080).$path);$responseHeaders=[];
curl_setopt_array($c,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_FOLLOWLOCATION=>false,CURLOPT_CONNECTTIMEOUT=>2,CURLOPT_TIMEOUT=>15,CURLOPT_USERAGENT=>$ua,CURLOPT_HTTPHEADER=>$headers,CURLOPT_ENCODING=>'',CURLOPT_COOKIEFILE=>'/scratch/'.($p['jar']??'default').'.cookies',CURLOPT_COOKIEJAR=>'/scratch/'.($p['jar']??'default').'.cookies',CURLOPT_HEADERFUNCTION=>static function($c,$h)use(&$responseHeaders){$kv=explode(':',$h,2);if(count($kv)===2 && in_array(strtolower(trim($kv[0])),['location','x-redirect-by','content-type','retry-after'],true))$responseHeaders[strtolower(trim($kv[0]))]=trim($kv[1]);return strlen($h);}]);
if(!empty($p['extended'])){ $backend=$p['backend_ip']??'127.0.0.3';if(!in_array($backend,['127.0.0.3','127.0.0.4'],true))throw new Exception('Expected private fixture listener');curl_setopt($c,CURLOPT_CONNECT_TO,['127.0.0.1:8080:'.$backend.':8080']); }
if(isset($p['post'])){curl_setopt($c,CURLOPT_POST,true);curl_setopt($c,CURLOPT_POSTFIELDS,http_build_query($p['post']));}
$body=curl_exec($c);if($body===false)throw new Exception(curl_error($c));
$summary=['marker'=>$p['marker'],'path'=>$path,'status'=>curl_getinfo($c,CURLINFO_RESPONSE_CODE),'headers'=>$responseHeaders,'body_bytes'=>strlen($body),'login_form'=>strpos($body,'name="log"')!==false,'target_content'=>strpos($body,'COMPAT_TARGET_CONTENT')!==false,'admin_screen'=>(bool)preg_match('/<body[^>]*class="[^"]*\bwp-admin\b/', $body),'critical_error'=>strpos($body,'There has been a critical error')!==false,'test_receipt'=>strpos($body,'"webdecoy_test":true')!==false,'wordfence_block'=>strpos($body,'Your access to this site has been limited')!==false || strpos($body,'Generated by Wordfence')!==false];
$summary['request_count_cells']=[];
preg_match_all('/data-webdecoy-outcome="([a-z]+)" data-window="([0-9]+)">([^<]*)<\/td>/', $body, $cells, PREG_SET_ORDER);
foreach($cells as $cell)$summary['request_count_cells'][$cell[1]][$cell[2]]=$cell[3]==='&mdash;'?null:(int)str_replace(',','',$cell[3]);
$summary['widget_counts']=[];
preg_match_all('/data-webdecoy-count="([a-z]+)">([0-9,]+)<\/span>/', $body, $widgets, PREG_SET_ORDER);
foreach($widgets as $widget)$summary['widget_counts'][$widget[1]]=(int)str_replace(',','',$widget[2]);
$summary['counter_error_visible']=strpos($body,'fixture counter write rejected')!==false || strpos($body,'WordPress database error')!==false;
$summary['tracking_start_visible']=strpos($body,'Request tracking started')!==false;
file_put_contents('/scratch/client-results.jsonl',json_encode($summary)."\n",FILE_APPEND|LOCK_EX);echo json_encode($summary);
